1	/*
2	 * Resolution of BaseText's typography props into an inline style object.
3	 * Server-safe (no "use client") — pure functions over plain values.
4	 *
5	 * Why inline instead of classes: a class-based prop only wins if it happens to
6	 * be emitted after the role's own class, which depends on bundler and import
7	 * order. Utilities such as `text-hero`/`font-hero` sit ~50kB before
8	 * `.text-style-body` in the compiled sheet, so as props they would do nothing.
9	 * Inline style outranks every layer, so a prop that is set beats any class;
10	 * only the consumer's own `style`, merged after it, overrides it.
11	 */
12	
13	import type { CSSProperties } from 'react';
14	import { toPxLength } from '../../utils/length';
15	import {
16	  ROLE_AXIS_TOKEN,
17	  type FontAxesValue,
18	  type FontSizeValue,
19	  type FontValue,
20	  type FontWeightValue,
21	  type LetterSpacingValue,
22	  type LineHeightValue,
23	  type TextVariant,
24	} from './constants';
25	
26	/** Numbers stay unitless — a line-height ratio scales with font-size, px does not. */
27	const toUnitless = (value: string | number | undefined) =>
28	  typeof value === 'number' ? String(value) : value;
29	
30	/**
31	 * `{ GRAD: 20, wdth: 110 }` → `"GRAD" 20, "wdth" 110`.
32	 * Axis tags are case-sensitive and must be quoted.
33	 */
34	export const serializeAxes = (axes: FontAxesValue): string =>
35	  Object.entries(axes)
36	    .filter(([, value]) => value !== undefined && value !== null && value !== '')
37	    .map(([axis, value]) => `"${axis}" ${value}`)
38	    .join(', ');
39	
40	export interface TextStyleProps {
41	  font?: FontValue;
42	  fontSize?: FontSizeValue;
43	  fontWeight?: FontWeightValue;
44	  lineHeight?: LineHeightValue;
45	  letterSpacing?: LetterSpacingValue;
46	  axes?: FontAxesValue;
47	  /**
48	   * Fixed-advance figures (`font-variant-numeric: tabular-nums`).
49	   *
50	   * Every digit takes the same width, so a number does not reflow as its digits
51	   * change — the reason to turn it on for anything that ticks, counts down, or
52	   * sits in a column that must align. It costs the proportional spacing the
53	   * face was drawn with, so it is opt-in rather than a default on body copy.
54	   *
55	   * `false` is not the same as omitting it: `false` writes
56	   * `proportional-nums`, forcing figures back to proportional even where an
57	   * ancestor turned tabular on. Omit to inherit.
58	   *
59	   * The face has to ship the `tnum` feature. Effectively all modern text faces
60	   * do; one that does not simply renders proportional figures, with no error.
61	   */
62	  tabular?: boolean;
63	}
64	
65	/**
66	 * Build the inline style for a set of typography props.
67	 *
68	 * Only props that were actually passed produce a declaration, so anything left
69	 * alone keeps falling through to the role class.
70	 *
71	 * @param variant  Role in play, used to prepend its axis token so `axes` MERGES
72	 *                 with the role's axes rather than replacing them. Pass
73	 *                 undefined when the role class is not applied (`unstyled`).
74	 */
75	export const buildTextStyle = (
76	  {
77	    font,
78	    fontSize,
79	    fontWeight,
80	    lineHeight,
81	    letterSpacing,
82	    axes,
83	    tabular,
84	  }: TextStyleProps,
85	  variant: TextVariant | undefined,
86	): CSSProperties | undefined => {
87	  const style: CSSProperties = {};
88	
89	  if (font !== undefined) style.fontFamily = font;
90	  if (fontSize !== undefined) style.fontSize = toPxLength(fontSize);
91	  if (fontWeight !== undefined) style.fontWeight = toUnitless(fontWeight);
92	  if (lineHeight !== undefined) style.lineHeight = toUnitless(lineHeight);
93	  if (letterSpacing !== undefined) style.letterSpacing = toPxLength(letterSpacing);
94	  /* Explicit both ways. `proportional-nums` rather than `normal` so passing
95	   * false overrides an inherited tabular run instead of merely declining to
96	   * set one. */
97	  if (tabular !== undefined) {
98	    style.fontVariantNumeric = tabular ? 'tabular-nums' : 'proportional-nums';
99	  }
100	
101	  if (axes !== undefined) {
102	    const own = serializeAxes(axes);
103	    if (own) {
104	      /* Duplicate axes resolve last-wins, so appending to the role's token
105	       * overrides just the axes named here and leaves the rest intact.
106	       * Roles without a token must not reference one: an undefined var makes
107	       * the whole declaration invalid, which would drop the axes entirely. */
108	      const roleAxes = variant ? ROLE_AXIS_TOKEN[variant] : undefined;
109	      style.fontVariationSettings = roleAxes ? `${roleAxes}, ${own}` : own;
110	    }
111	  }
112	
113	  return Object.keys(style).length > 0 ? style : undefined;
114	};
