1	/*
2	 * check-conventions.mjs — the design system's measurable rules, run by
3	 * `npm run lint` after `tsc --noEmit`.
4	 *
5	 * ## behavior
6	 * - `node scripts/check-conventions.mjs` runs every check in CHECKS over src/
7	 *   (.ts/.tsx/.css). Each violation prints one line,
8	 *   `FAIL <check name>: <file:line> <match>`, then each failed check prints its
9	 *   one-line why, and the script exits 1. With no violation it prints
10	 *   `conventions: N checks passed` and exits 0.
11	 * - `--fixtures [dir]` (dir defaults to scripts/check-conventions.fixtures/)
12	 *   runs the checks that have fixtures over that dir instead of src/, with the
13	 *   dir's allowlists.json in place of the allowlists below. It exits 0 only when
14	 *   every fixture file `<check-id>[.<case>].<ext>` is reported exactly once, by
15	 *   the check with that id, every other file (`*.ok.*` near-misses and support
16	 *   files) reports nothing, and every check reports at least one file. See the
17	 *   fixture dir's README.txt.
18	 * - Repo-level checks (`fixtures: false`, e.g. the generated-theme check) run
19	 *   only in the normal mode, because they read fixed paths, not the scan root.
20	 * - Paths are root-relative for scoping (`components/Text/`, `styles/tokens.css`)
21	 *   and repo-relative in output, so the same scoping holds in fixture mode.
22	 *
23	 * ## Adding a check
24	 * Append ONE object to CHECKS, nothing else:
25	 *   { id, name, why, run(ctx) => Violation[] }          // code check: add a fixture
26	 *   { id, name, why, fixtures: false, run(ctx) => [...] } // repo-level check
27	 * - `id` is kebab-case; it names the check's fixture files.
28	 * - `name` and `why` are quoted verbatim by the maintainer skills.
29	 * - A Violation is { file, line, match }. `file` is repo-relative (use `f.path`
30	 *   for a scanned file, or `repoRel(abs)` for anything else).
31	 * - `ctx.files` holds every scanned file as { path, rel, ts, css, story,
32	 *   generated, raw, code } where `code` is the source with comments blanked out
33	 *   (offsets and line numbers unchanged). Match `code`, never `raw`. Helpers:
34	 *   `scan(files, regex)` (every match is a violation) and `lineOf(code, index)`.
35	 * - A repo-level check that wraps a generator calls the generator's own
36	 *   write-nothing `--check` mode with `runCheckMode()`, as the generated-theme
37	 *   check does with sync-theme.mjs.
38	 *
39	 * ## constraints
40	 * - Check names and whys are a contract: the maintainer skills cite them word
41	 *   for word ("lint check: text-style classes outside Text components").
42	 *   Renaming one means updating every skill that cites it, in the same change.
43	 * - Code checks match comment-blanked source. A header contract must be able to
44	 *   name a forbidden class without failing lint, and line numbers must stay true.
45	 * - Lint stays fast: no browser, no build, no network, nothing written. A repo
46	 *   check calls a generator only through its in-memory `--check` mode.
47	 * - A regex fix that removes a false positive keeps its fixture catching the
48	 *   real violation; add the near-miss to that fixture so it cannot come back.
49	 * - Every allowlist entry carries a reason and `needs`, the APIs the reason
50	 *   names. An entry whose file is gone, lost its directive or timer, or no
51	 *   longer uses what `needs` names FAILS, so the list cannot rot. Fix the entry
52	 *   (or the code), never the matching, to make it pass.
53	 */
54	import fs from "node:fs";
55	import path from "node:path";
56	import { spawnSync } from "node:child_process";
57	import { fileURLToPath } from "node:url";
58	
59	const REPO = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
60	const DEFAULT_FIXTURES = "scripts/check-conventions.fixtures";
61	const posix = (p) => p.split(path.sep).join("/");
62	const repoRel = (abs) => posix(path.relative(REPO, abs));
63	const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
64	
65	// ── Source loading ────────────────────────────────────────────────────────────
66	const blank = (s) => s.replace(/[^\n]/g, " ");
67	/** Blank out comments, keeping every offset (so line numbers stay true). */
68	function stripComments(src, ts) {
69	  let out = src.replace(/\/\*[\s\S]*?\*\//g, blank);
70	  // `//` not preceded by `:` (URLs), a quote or a backslash.
71	  if (ts) out = out.replace(/(^|[^:"'`\\])(\/\/.*)$/gm, (_, a, b) => a + blank(b));
72	  return out;
73	}
74	const GENERATED_BLOCK = /\/\* __GENERATED_THEME_START__ \*\/[\s\S]*?\/\* __GENERATED_THEME_END__ \*\//;
75	
76	function loadFiles(root) {
77	  const out = [];
78	  const walk = (d) => {
79	    for (const e of fs.readdirSync(d, { withFileTypes: true })) {
80	      const p = path.join(d, e.name);
81	      if (e.isDirectory()) walk(p);
82	      else if (/\.(tsx?|css)$/.test(e.name)) {
83	        const rel = posix(path.relative(root, p));
84	        const ts = /\.tsx?$/.test(rel);
85	        const raw = fs.readFileSync(p, "utf8");
86	        out.push({
87	          path: repoRel(p),
88	          rel,
89	          ts,
90	          css: !ts,
91	          story: /\.stories\.tsx?$/.test(rel),
92	          // Written by scripts (sync-theme.mjs, generate-icon-exports.mjs).
93	          // Their freshness is checked by the generators' own --check modes.
94	          generated: rel === "styles/theme.css" || rel === "components/Icons/index.ts",
95	          raw,
96	          code: stripComments(raw, ts).replace(GENERATED_BLOCK, blank),
97	        });
98	      }
99	    }
100	  };
101	  walk(root);
102	  return out.sort((a, b) => (a.path < b.path ? -1 : 1));
103	}
104	
105	const lineOf = (s, i) => {
106	  let n = 1;
107	  for (let k = 0; k < i; k++) if (s.charCodeAt(k) === 10) n++;
108	  return n;
109	};
110	const short = (s) => s.replace(/\s+/g, " ").trim().slice(0, 80);
111	/** Every match of `re` (global) in each file's comment-blanked code is a violation. */
112	function scan(files, re, keep = () => true) {
113	  const v = [];
114	  for (const f of files)
115	    for (const m of f.code.matchAll(re))
116	      if (keep(m, f)) v.push({ file: f.path, line: lineOf(f.code, m.index), match: short(m[0]) });
117	  return v;
118	}
119	
120	// File sets shared by the checks (all non-generated):
121	//   code(ctx)  .ts/.tsx/.css, stories excluded       codeTs(ctx) the .ts/.tsx part
122	//   tsx(ctx)   .ts/.tsx, stories included             text(ctx)   tsx minus the Text exemption
123	const code = (ctx) => ctx.files.filter((f) => !f.story && !f.generated);
124	const codeTs = (ctx) => code(ctx).filter((f) => f.ts);
125	const tsx = (ctx) => ctx.files.filter((f) => f.ts && !f.generated);
126	// The Text components and the tailwind-merge registry must name the role classes.
127	const TEXT_EXEMPT = (f) =>
128	  f.rel.startsWith("components/Text/") || f.rel === "utils/cn.ts" || f.rel === "utils/twMergeTheme.ts";
129	const text = (ctx) => tsx(ctx).filter((f) => !TEXT_EXEMPT(f));
130	const TOKENS_REL = "styles/tokens.css";
131	
132	/** Run a generator's write-nothing `--check` mode; each `stale <path>` line it prints is a violation. */
133	function runCheckMode(script) {
134	  const r = spawnSync(process.execPath, [path.join(REPO, script), "--check"], { cwd: REPO, encoding: "utf8" });
135	  if (r.status === 0) return [];
136	  const stale = (r.stdout || "").split("\n").map((l) => l.match(/^stale (\S+)/)).filter(Boolean);
137	  if (stale.length) return stale.map((m) => ({ file: m[1], line: 1, match: `out of date; run node ${script}` }));
138	  return [{ file: script, line: 1, match: `--check failed: ${short(r.stderr || r.stdout || `exit ${r.status}`)}` }];
139	}
140	
141	// ── Allowlists ────────────────────────────────────────────────────────────────
142	// `needs`: what the reason says the file uses. A string is matched as a whole
143	// identifier (or dotted name like navigator.clipboard) in the comment-blanked
144	// code; a RegExp as written.
145	const USE_CLIENT_ALLOWLIST = [
146	  { file: "src/components/AIChat/AIModelSelect.tsx", needs: [/\bonValueChange=\{\(/],
147	    reason: "Builds an inline onValueChange closure for SliderLabeled that maps the slider index back to the consumer's step value." },
148	  { file: "src/components/AIChat/AIPromptInput.tsx", needs: ["createContext", "useState", "useLayoutEffect"],
149	    reason: "createContext shares the composer state with its parts, useState holds the uncontrolled value, useLayoutEffect sizes the textarea to its scrollHeight." },
150	  { file: "src/components/AIChat/AIThinkingPart.tsx", needs: ["useState"],

150	  { file: "src/components/AIChat/AIThinkingPart.tsx", needs: ["useState"],
151	    reason: "useState holds the uncontrolled disclosure open state." },
152	  { file: "src/components/AnimatedText/ChangeSwapShell.tsx", needs: ["useChangeSwap"],
153	    reason: "Calls useChangeSwap, whose useState/useRef keep the outgoing copy mounted until its animationend." },
154	  { file: "src/components/AnimatedText/RevealChangeText.tsx", needs: ["useState", "useRef", "useEffect", "ResizeObserver"],
155	    reason: "useState/useRef/useEffect run the collapse-then-reveal slot; a ResizeObserver measures the content width the slot animates to." },
156	  { file: "src/components/AnimatedText/RollingDigitsText.tsx", needs: ["useState"],
157	    reason: "useState (inside useWheels) holds every digit wheel, reconciled during render." },
158	  { file: "src/components/AnimatedText/useChangeSwap.ts", needs: ["useState", "useRef"],
159	    reason: "The swap engine: useState holds the exiting and entering copies, useRef the content on screen." },
160	  { file: "src/components/Calendar/Calendar.tsx", needs: ["useState", "useRef", "useEffect"],
161	    reason: "useState holds the uncontrolled month, range anchor, hovered and focused day; useRef + useEffect restore focus to the focused day." },
162	  { file: "src/components/Calendar/CalendarCaption.tsx", needs: [/\bonSelect=\{\(\)\s*=>/, /\bonClick=\{\(\)\s*=>/],
163	    reason: "Builds inline onSelect/onClick closures for the month and year menus and the previous/next buttons." },
164	  { file: "src/components/Calendar/CalendarGrid.tsx", needs: [/\bonClick=\{\(\)\s*=>/, /\bonPointerEnter=\{\(\)\s*=>/],
165	    reason: "Attaches per-day onClick/onPointerEnter closures to the day buttons." },
166	  { file: "src/components/Calendar/CalendarPresetsPanel.tsx", needs: [/\bonClick=\{\(event\)\s*=>/],
167	    reason: "Attaches an inline onClick closure to each preset button." },
168	  { file: "src/components/CopyButton/CopyButton.tsx", needs: ["navigator.clipboard", "useState", "setTimeout"],
169	    reason: "Writes to navigator.clipboard, holds the copied state in useState and reverts it with setTimeout." },
170	  { file: "src/components/DatePicker/DatePicker.tsx", needs: [/\bonValueChange=\{props\.onValueChange\}/],
171	    reason: "No client hook of its own: it forwards the required onValueChange callback (and onOpenChange) into Calendar and Popover, so only client code can render it." },
172	  { file: "src/components/DatePicker/DatePickerSplitTrigger.tsx", needs: [/\bconst handlePresetChange\s*=/],
173	    reason: "Builds the handlePresetChange closure that turns a preset tab into its date range for onValueChange." },
174	  { file: "src/components/DropdownTrigger/DropdownTrigger.tsx", needs: ["useRef", /\bonKeyDown=\{\(event\)\s*=>/],
175	    reason: "useRef holds the input element, which the inline pointer and key handlers focus before Radix opens the menu." },
176	  { file: "src/components/Input/Input.tsx", needs: ["useState", "useRef"],
177	    reason: "useState holds the uncontrolled value, focus and committed value; useRef holds the input element." },
178	  { file: "src/components/Menu/DropdownMenu.tsx", needs: ["createContext", "useContext", "document.hasFocus"],
179	    reason: "createContext/useContext pass selectType to the items; the focus-loss guard reads document.hasFocus and document.contains." },
180	  { file: "src/components/Menu/DropdownMenuSearch.tsx", needs: [/\bconst handleKeyDown\s*=/],
181	    reason: "Builds the handleKeyDown closure that stops key events reaching the menu's typeahead." },
182	  { file: "src/components/MorphRotationShape/MorphRotationShape.tsx",
183	    needs: ["useState", "useRef", "useLayoutEffect", "requestAnimationFrame", "getComputedStyle", "addEventListener"],
184	    reason: "A requestAnimationFrame loop samples transitioned custom properties with getComputedStyle, wired in useLayoutEffect with addEventListener; useState/useRef hold the engine." },
185	  { file: "src/components/OutlineButton/OutlineButton.tsx", needs: ["useRef", "getBoundingClientRect"],
186	    reason: "The mouse-move handler reads getBoundingClientRect on a useRef element and writes the glow position as custom properties." },
187	  { file: "src/components/SegmentedTabSelect/SegmentedTabSelect.tsx", needs: ["createContext", "useContext"],
188	    reason: "createContext/useContext pass the tab variant and item size from the group to its items." },
189	  { file: "src/components/SidebarWithHoverIcon/SidebarWithHoverIcon.tsx",
190	    needs: ["useRef", "useLayoutEffect", "requestAnimationFrame", "getComputedStyle"],
