62	 *   `input.value` imperatively through the ref bypasses it — set `value`
63	 *   instead. The consumer's `onChange` always still runs.
64	 * - With `format` on the `<input>` is always controlled by this component (the
65	 *   displayed text differs from the raw value), so the DOM `value` is the
66	 *   display text and `defaultValue` is never passed down. Raw state stays
67	 *   `value` or the component's own state, never the display text, or blur
68	 *   would re-parse formatted text.
69	 * - Input filtering happens at entry, never as a validation error after the
70	 *   fact: an invalid character must not reach the DOM value, `onChange` or
71	 *   `onValueChange`. Range errors are DERIVED from the committed value on
72	 *   every render and never stored, and `hasError` always overrides them, so
73	 *   a consumer's own validation can't be fought by the automatic one. Never
74	 *   clamp `value`: the consumer decides what to do with an out-of-range number.
75	 * - `InputVariant.text` without `icon` stays a bare `<input>`: existing
76	 *   consumers style and measure that element directly, and wrapping it would
77	 *   move their `className` onto a different node.
78	 * - An icon variant without an `icon` element (null, false, "" included)
79	 *   throws. The props union is the real guard (`icon` is a `ReactElement`);
80	 *   the throw covers JavaScript consumers and runtime-computed variants —
81	 *   rendering a variant with an empty icon slot would silently misreport what
82	 *   was asked for (same rule as SliderVariant.custom).
83	 */
84	"use client";
85	
86	import {
87	  forwardRef,
88	  isValidElement,
89	  useMemo,
90	  useRef,
91	  useState,
92	  type ChangeEvent,
93	  type FocusEvent,
94	  type InputEvent as ReactInputEvent,
95	  type InputHTMLAttributes,
96	  type PointerEvent,
97	  type ReactElement,
98	} from "react";
99	import { cn } from "../../utils/cn";
100	import { BaseText, ButtonText, TextVariant } from "../Text";
101	import { useComposedRefs } from "../../utils/composeRefs";
102	import { InputVariant } from "./constants";
103	
104	type InputBaseProps = Omit<InputHTMLAttributes<HTMLInputElement>, "min" | "max"> & {
105	  /**
106	   * Forces the error chrome and `aria-invalid` on (`true`) or off (`false`).
107	   * Omit it to let `min` / `max` decide on number variants.
108	   */
109	  hasError?: boolean;
110	  /**
111	   * Number variants: lowest allowed value. Also decides whether a leading minus
112	   * can be typed (only when `min` is undefined or negative). Out-of-range
113	   * committed values show the error state; the value is never clamped.
114	   */
115	  min?: number;
116	  /** Number variants: highest allowed value; out-of-range shows the error state, never clamps. */
117	  max?: number;
118	  /** Number variants: hug the value instead of filling the container. Default off. */
119	  autoWidth?: boolean;
120	  /**
121	   * Number variants: show the value formatted with `Intl.NumberFormat` while the
122	   * field is not focused (raw while focused). `true` keeps every fraction digit;
123	   * pass options to control them. Default off.
124	   */
125	  format?: boolean | Intl.NumberFormatOptions;
126	  /** BCP 47 locale for `format`. Pass it for SSR-stable output. Default: the runtime's. */
127	  locale?: string;
128	  /** Fires on every change with the raw string (separators stripped when `format` is on). */
129	  onValueChange?: (value: string) => void;
130	};
131	
132	type NumberSeparators = { group: string; decimal: string };
133	
134	const NUMBER_PATTERN = /^-?\d+(\.\d+)?$/;
135	const WHITESPACE = /[\s  ]/g;
136	const escapeRegExp = (text: string) =>
137	  text.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
138	
139	const DEFAULT_SEPARATORS: NumberSeparators = { group: ",", decimal: "." };
140	
141	/**
142	 * Keeps only what a number field may show: digits, one decimal separator and,
143	 * when allowed, a leading minus. Grouping separators and whitespace are
144	 * stripped. The decimal stays the locale's (display form).
145	 */
146	function sanitizeNumberText(
147	  text: string,
148	  { group, decimal }: NumberSeparators,
149	  allowNegative: boolean,
150	) {
151	  let rest = text.replace(WHITESPACE, "");
152	  if (group) rest = rest.replace(new RegExp(escapeRegExp(group), "g"), "");
153	  let out = "";
154	  let hasDecimal = false;
155	  for (const char of rest) {
156	    if (char >= "0" && char <= "9") out += char;
157	    else if (char === decimal && !hasDecimal) {
158	      hasDecimal = true;
159	      out += char;
160	    } else if ((char === "-" || char === "\u2212") && allowNegative && out === "") {
161	      out = "-";
162	    }
163	  }
164	  return out;
165	}
166	
167	/** Display text (locale decimal) to a raw numeric string ("." decimal). */
168	function toRaw(text: string, { decimal }: NumberSeparators) {
169	  return decimal === "." ? text : text.replace(decimal, ".");
170	}
171	
172	function isOutOfRange(raw: string, min?: number, max?: number) {
173	  if (raw.trim() === "") return false;
174	  const n = Number(raw);
175	  if (!Number.isFinite(n)) return false;
176	  return (min !== undefined && n < min) || (max !== undefined && n > max);
177	}
178	
179	export type InputProps =
180	  | (InputBaseProps & {
181	      variant?: typeof InputVariant.text | typeof InputVariant.number;
182	      icon?: never;
183	    })
184	  | (InputBaseProps & {
185	      variant: typeof InputVariant.iconText | typeof InputVariant.iconNumber;
186	      /** Leading icon, e.g. <PencilIcon />. Sized by the icon itself (14px default). */
187	      icon: ReactElement;
188	    });
189	
190	/** Text or number field whose `className` lands on the field chrome (the
191	 * `<input>` itself for the text variant, the wrapper otherwise), while `ref`,
192	 * `style` and every other prop land on the `<input>`. */
193	const Input = forwardRef<HTMLInputElement, InputProps>(
194	  (
195	    {
196	      className,
197	      hasError,
198	      variant = InputVariant.text,
199	      icon,
200	      value,
201	      defaultValue,
202	      onChange,
203	      onBeforeInput,
204	      onValueChange,
205	      min,
206	      max,
207	      onFocus,
208	      onBlur,
209	      autoWidth,
210	      format,
211	      locale,
212	      placeholder,
213	      disabled,
214	      ...props
215	    },
216	    ref,
217	  ) => {
218	    const isNumber =
219	      variant === InputVariant.number || variant === InputVariant.iconNumber;
220	    const hasIcon =
221	      variant === InputVariant.iconText || variant === InputVariant.iconNumber;
222	
223	    const inputEl = useRef<HTMLInputElement | null>(null);
224	    const setRefs = useComposedRefs(inputEl, ref);
225	
226	    const isControlled = value !== undefined;
227	    const [uncontrolledValue, setUncontrolledValue] = useState(() =>
228	      String(defaultValue ?? ""),
229	    );
230	
231	    // Format on blur — see the header. Off unless asked, and number variants only.
232	    const formatOn = isNumber && !!format;
233	    const formatKey = typeof format === "object" ? JSON.stringify(format) : !!format;
234	    const formatting = useMemo(() => {
235	      if (!formatOn) return null;
236	      const options: Intl.NumberFormatOptions =
237	        typeof format === "object" ? format : { maximumFractionDigits: 20 };
238	      const parts = new Intl.NumberFormat(locale, {
239	        minimumFractionDigits: 1,
240	        useGrouping: true,
241	      }).formatToParts(11111.1);
242	      return {
243	        formatter: new Intl.NumberFormat(locale, options),
244	        separators: {
245	          group: parts.find((part) => part.type === "group")?.value ?? "",
246	          decimal: parts.find((part) => part.type === "decimal")?.value ?? ".",
247	        },
248	      };
249	      // formatKey stands in for `format`: an inline options object changes identity every render.
250	      // eslint-disable-next-line react-hooks/exhaustive-deps
251	    }, [formatOn, formatKey, locale]);
252	    const [focused, setFocused] = useState(false);
253	    // The value as of the last blur (uncontrolled range check) — see the header.
254	    const [committedValue, setCommittedValue] = useState(() =>
255	      String(defaultValue ?? ""),
256	    );
257	
258	    // Entry filter — see the header. Number variants only.
259	    const separators = formatting?.separators ?? DEFAULT_SEPARATORS;
260	    const allowNegative = min === undefined || min < 0;
261	
262	    const handleBeforeInput = (event: ReactInputEvent<HTMLInputElement>) => {
263	      onBeforeInput?.(event);
264	      if (event.defaultPrevented || (event.nativeEvent as InputEvent).isComposing) {
265	        return;
266	      }
267	      const { data } = event;
268	      const input = event.currentTarget;
269	      if (!data || input.selectionStart === null || input.selectionEnd === null) {
270	        return;
271	      }
272	      const before = input.value.slice(0, input.selectionStart);
273	      const after = input.value.slice(input.selectionEnd);
274	      // Block only an insertion that adds nothing valid; a partly valid paste
275	      // goes through and handleChange sanitises it.
276	      const kept = sanitizeNumberText(before + after, separators, allowNegative);
277	      const next = sanitizeNumberText(before + data + after, separators, allowNegative);
278	      if (next === kept) event.preventDefault();
279	    };
280	
281	    const handleChange = (event: ChangeEvent<HTMLInputElement>) => {
282	      let display = event.target.value;
283	      if (isNumber) {
284	        const caret = event.target.selectionStart ?? display.length;
285	        const clean = sanitizeNumberText(display, separators, allowNegative);
286	        if (clean !== display) {
287	          const cleanCaret = sanitizeNumberText(
288	            display.slice(0, caret),
289	            separators,
290	            allowNegative,
291	          ).length;
292	          // Before onChange, so the consumer reads the sanitised text.
293	          event.target.value = clean;
294	          event.target.setSelectionRange(cleanCaret, cleanCaret);
295	          display = clean;
296	        }
297	      }
298	      const raw = formatting ? toRaw(display, formatting.separators) : display;
299	      if (!isControlled) setUncontrolledValue(raw);
300	      onChange?.(event);
301	      onValueChange?.(raw);
302	    };
303	    const handleFocus = (event: FocusEvent<HTMLInputElement>) => {
304	      if (formatting) setFocused(true);
305	      onFocus?.(event);
306	    };
307	    const handleBlur = (event: FocusEvent<HTMLInputElement>) => {
308	      if (formatting) setFocused(false);
309	      setCommittedValue(rawValue);
310	      onBlur?.(event);
311	    };
312	
313	    const rawValue = isControlled ? String(value) : uncontrolledValue;
314	    // Range errors are derived, and hasError always wins — see the header.
315	    const outOfRange =
316	      isNumber &&
317	      isOutOfRange(isControlled ? rawValue : committedValue, min, max);
318	    const showError = hasError ?? outOfRange;
319	    let displayValue: string | undefined;
320	    if (formatting) {
321	      if (focused) {
322	        displayValue =
323	          formatting.separators.decimal === "."
324	            ? rawValue
325	            : rawValue.replace(".", formatting.separators.decimal);
326	      } else {
327	        displayValue = NUMBER_PATTERN.test(rawValue)
328	          ? formatting.formatter.format(rawValue as unknown as number)
329	          : rawValue;
330	      }
331	    }
332	
333	    if (hasIcon && !isValidElement(icon)) {
334	      throw new Error(
335	        `[Input] variant "${variant}" requires an \`icon\` element, e.g. icon={<PencilIcon />}.`,
336	      );
337	    }
338	
339	    const fieldProps = {
340	      // Before ...props, so a consumer's explicit aria-invalid still wins
341	      // (the CodeDigitInput order).
342	      "aria-invalid": showError || undefined,
343	      ...(isNumber
344	        ? { inputMode: "decimal" as const, onBeforeInput: handleBeforeInput }
345	        : { onBeforeInput, min, max }),
346	      ...props,
347	      ref: setRefs,
348	      // With `format` the input is always controlled by the display text — see the header.
349	      value: formatting ? displayValue : value,
350	      defaultValue: formatting ? undefined : defaultValue,
351	      onChange: handleChange,
352	      onFocus: handleFocus,
353	      onBlur: handleBlur,
354	      placeholder,
355	      disabled,
356	    };
357	
358	    if (!isNumber && !hasIcon) {
359	      return (
360	        <ButtonText
361	          as="input"
362	          {...fieldProps}
363	          className={cn(
364	            "flex h-button w-full rounded-tight border border-solid border-border-primary bg-secondary",
365	            "pl-md pr-rg",
366	            "text-text placeholder:text-text-tertiary",
367	            "ds-motion-state ds-focus-ring-on-focus",
368	            // `enabled:` keeps a disabled input from lifting; `not-focus:` keeps the
369	            // focus border winning over the hover border while the field is
370	            // both hovered and focused.
371	            "enabled:hover:not-focus:border-input-border-hover enabled:hover:shadow-button-secondary",
372	            "focus:border-input-border-focus",
373	            "disabled:bg-secondary-disabled disabled:border-secondary-border-disabled ds-disabled-state",
374	            showError &&
375	              "border-danger-primary focus:border-input-border-danger-focus ds-focus-ring-danger-on-focus",
376	            className,
377	          )}
378	        />
379	      );
380	    }
381	
382	    const fieldRole = isNumber ? TextVariant.mono : TextVariant.button;
383	    const innerInputClass = cn(
384	      "min-w-0 bg-transparent outline-none",
385	      "text-text placeholder:text-text-tertiary ds-disabled-state",
386	    );
387	
388	    // Chrome clicks focus the field; the input handles its own pointer events.
389	    const focusFromChrome = (event: PointerEvent<HTMLDivElement>) => {
390	      if (disabled || event.target === inputEl.current) return;
391	      event.preventDefault();
392	      inputEl.current?.focus();
393	    };
394	
395	    const hugs = isNumber && !!autoWidth;
396	    const mirrorText = (displayValue ?? rawValue) || placeholder || "";
397	
398	    return (
399	      <div
400	        onPointerDown={focusFromChrome}
401	        data-disabled={disabled ? "" : undefined}
402	        className={cn(
403	          "h-button items-center rounded-tight border border-solid border-border-primary bg-secondary",
404	          "ds-motion-state ds-focus-within-ring",
405	          hugs
406	            ? "inline-flex min-w-button justify-center pl-md pr-md"
407	            : isNumber
408	              ? "flex w-full min-w-button pl-md pr-md"
409	              : "flex w-full pl-md pr-rg",
410	          hasIcon && (isNumber ? "gap-xxs" : "gap-sm"),
411	          "cursor-text data-[disabled]:cursor-not-allowed data-[disabled]:bg-secondary-disabled",
412	          // The error border wins over the disabled one: the disabled border
413	          // applies only when there is no error.
414	          !showError && "data-[disabled]:border-secondary-border-disabled",
415	          !showError &&
416	            "[&:hover:not(:focus-within):not([data-disabled])]:border-input-border-hover [&:hover:not(:focus-within):not([data-disabled])]:shadow-button-secondary",
417	          "focus-within:border-input-border-focus",
418	          showError &&
419	            "border-danger-primary focus-within:border-input-border-danger-focus ds-focus-within-ring-danger",
420	          className,
421	        )}
422	      >
423	        {hasIcon && (
424	          <span
425	            aria-hidden
426	            className={cn(
427	              "flex shrink-0 text-text",
428	              disabled && "ds-opacity-disabled",
429	            )}
430	          >
431	            {icon}
432	          </span>
433	        )}
434	        {hugs ? (
435	          <span className="inline-grid min-w-0">
436	            {/* Sizes the cell to the value — see the header. */}
437	            <BaseText
438	              aria-hidden
439	              variant={fieldRole}
440	              className="invisible whitespace-pre [grid-area:1/1] pr-px"
441	            >
442	              {mirrorText}
443	            </BaseText>
444	            <BaseText
445	              as="input"
446	              variant={fieldRole}
447	              {...fieldProps}
448	              // w-0 + min-w-full: contributes nothing to the cell's size (its
449	              // ~20ch intrinsic width would prop the cell open), then fills it.
450	              className={cn(innerInputClass, "[grid-area:1/1] w-0 min-w-full")}
451	            />
452	          </span>
453	        ) : (
454	          <BaseText
455	            as="input"
456	            variant={fieldRole}
457	            {...fieldProps}
458	            className={cn("h-full flex-1", innerInputClass)}
459	          />
460	        )}
461	      </div>
462	    );
463	  },
464	);
465	
466	Input.displayName = "Input";
467	
468	export { Input };
469

