1	import { useState } from 'react';
2	import type { Meta, StoryObj } from '@storybook/react-vite';
3	import { Checkbox } from './Checkbox';
4	import {
5	  CheckboxChecked,
6	  CheckboxVariant,
7	  type CheckboxChecked as CheckboxCheckedValue,
8	} from './constants';
9	import { LabelText } from '../Text';
10	
11	const meta = {
12	  title: 'Inputs/Checkbox',
13	  component: Checkbox,
14	  parameters: { layout: 'centered' },
15	  tags: ['autodocs'],
16	  argTypes: {
17	    variant: {
