import { useState } from 'react';
import type { Meta, StoryObj } from '@storybook/react-vite';
import { CheckboxField } from './CheckboxField';
import {
  CheckboxChecked,
  CheckboxVariant,
  type CheckboxChecked as CheckboxCheckedValue,
} from '../Checkbox/constants';

const meta = {
  title: 'Inputs/CheckboxField',
  component: CheckboxField,
  parameters: { layout: 'centered' },
  tags: ['autodocs'],
  argTypes: {
    variant: {
      control: 'select',
      options: Object.values(CheckboxVariant),
    },
  },
} satisfies Meta<typeof CheckboxField>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  args: {
    label: 'Enable notifications',
  },
};

export const WithHint: Story = {
  args: {
    label: 'Enable notifications',
    hint: 'We will send you an email when something important happens.',
  },
};

export const Checked: Story = {
  args: {
    label: 'Accept terms and conditions',
    defaultChecked: true,
  },
};

export const CheckedWithHint: Story = {
  args: {
    label: 'Accept terms and conditions',
    hint: 'You must accept the terms before continuing.',
    defaultChecked: true,
  },
};

export const Primary: Story = {
  args: {
    label: 'Remember me',
    variant: CheckboxVariant.primary,
    defaultChecked: true,
  },
};

export const Disabled: Story = {
  args: {
    label: 'This option is unavailable',
    hint: 'Contact an administrator to change this setting.',
    disabled: true,
  },
};

export const DisabledChecked: Story = {
  args: {
    label: 'This option is locked',
    disabled: true,
    defaultChecked: true,
  },
};

export const Controlled: Story = {
  render: function ControlledStory() {
    const [checked, setChecked] = useState<CheckboxCheckedValue>(
      CheckboxChecked.unchecked,
    );

    return (
      <CheckboxField
        label={checked === CheckboxChecked.checked ? 'Enabled' : 'Disabled'}
        hint="Toggle this setting on or off."
        checked={checked}
        onCheckedChange={setChecked}
      />
    );
  },
};

export const AllVariants: Story = {
  render: () => (
    <div className="flex flex-col gap-lg">
      {Object.values(CheckboxVariant).map((variant) => (
        <CheckboxField
          key={variant}
          variant={variant}
          defaultChecked
          label={`${variant} variant`}
          hint={`This is the ${variant} checkbox variant.`}
        />
      ))}
    </div>
  ),
};

